#[test]
fn percents_per_second() {
    for v in [1.0, 0.3, -42.75, 1e6, 123456.789] {
        // Generated conversion vs. the upstream formula, verbatim.
        let x: f64 = v;
        let base = x / 1e2;
        assert_close(
            RatioChangeRate::from_percents_per_second(v).as_base(),
            base,
            F64_TOL,
        );
        let x: f64 = base;
        let back = x * 1e2;
        assert_close(
            RatioChangeRate::from_base(base).as_percents_per_second(),
            back,
            F64_TOL,
        );
        assert_close(
            RatioChangeRate::from_percents_per_second(v).as_percents_per_second(),
            v,
            ROUND_TRIP_TOL,
        );
        // f32 storage.
        assert_close(
            RatioChangeRate::from_percents_per_second(v as f32).as_base() as f64,
            base,
            F32_TOL,
        );
        assert_close(
            RatioChangeRate::from_base(base as f32).as_percents_per_second() as f64,
            back,
            F32_TOL,
        );
    }
}

